js, _ := nc.JetStream()
sub, _ := js.PullSubscribe("orders", "billing-ledger", nats.DeliverAllAvailable())
for {
    msgs, _ := sub.Fetch(100, nats.MaxWait(2*time.Second))   // bounded catch-up batch
    for _, m := range msgs {
        handle(m)      // idempotent
        m.Ack()        // checkpoint after the side effect
    }
}

